// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;

    // Accept ether so owner (= this test contract) can receive the withdrawal
    receive() external payable {}

    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint128).max);

        // fund the token contract directly
        vm.deal(address(c), amount);
        assert(address(c).balance == amount);

        // owner is msg.sender at construction = this test contract; withdraw()
        bool ok = true;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && address(c).balance == 0);
    }
}
